              "originalRecord": {
                "factId": "proof.result.valid",
                "status": "PROPOSED_NOT_ACCEPTED",
                "cataloguePointer": "/facts/17",
                "values": {
                  "wahr": "Eine vorhandene korrekt gebundene Antwortbeobachtungskette ist gueltig, ob der Zahlenfakt wahr oder falsch ist. Vollstaendig belegte, aber nicht fachlich definitive Beobachtung (etwa reine automatische Uebernahme) kann bei unbekanntem Zahlenfakt gueltig sein; daraus folgt kein Leistungsclaim.",
                  "falsch": "Explizite Invalidierung eines notwendigen Anfangs-, Abgabe-, Antwort-, Eingabe- oder erforderlichen Lesartbelegs; kein gueltiger unabhängiger Ersatz.",
                  "unbekannt": "Keine Antwortkette, fehlende notwendige Eingabe/Lesart/Abgabe oder unsichere Aktivitaet nach Luecke ohne frische Beobachtung. Die gueltige Beobachtung der Antwortabwesenheit ersetzt keine typisierte Ergebniskette."
                },
                "necessaryDependencies": [
                  "Anfang/Aufgabe",
                  "Abgabe",
                  "vorhandene Antwortbeobachtung",
                  "Eingabeprovenienz",
                  "notwendige Lesart",
                  "aktuelle Antwortaktivitaet"
                ],
                "guardsFacts": [
                  "answer.value.15"
                ],
                "authority": [
